import{_ as a,o as i,c as t,a5 as s}from"./chunks/framework.BrSBneze.js";const h=JSON.parse('{"title":"Open call: activities of daily living","description":"Contribute reproducible HiveBoard mechanisms for activities of daily living.","frontmatter":{"description":"Contribute reproducible HiveBoard mechanisms for activities of daily living."},"headers":[],"relativePath":"contribute/adl.md","filePath":"contribute/adl.md","lastUpdated":1788882780000}'),o={name:"contribute/adl.md"};function r(n,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="open-call-activities-of-daily-living" tabindex="-1">Open call: activities of daily living <a class="header-anchor" href="#open-call-activities-of-daily-living" aria-label="Permalink to &quot;Open call: activities of daily living&quot;">​</a></h1><p>We seek functional assets representing <strong>activities of daily living (ADL)</strong> for evaluation with robot grippers, dexterous hands, and prosthetic hands.</p><p>The asset should reproduce a useful part of an everyday task, with a repeatable initial state and an observable success condition. A working closure, for example, should require the intended release motion and retain the object when closed.</p><h2 id="suitable-proposals" tabindex="-1">Suitable proposals <a class="header-anchor" href="#suitable-proposals" aria-label="Permalink to &quot;Suitable proposals&quot;">​</a></h2><p>Possible directions include:</p><ul><li>opening and closing container lids or household latches;</li><li>fastening and releasing buckles or clothing fasteners;</li><li>pressing a dispenser and collecting the released item; and</li><li>manipulating household controls with a defined sequence of motions.</li></ul><p>These are examples to discuss with the authors, not a list of approved designs. Explain what manipulation requirement the asset adds beyond the <a href="/hiveboard-docs/hardware/modules">existing mechanisms</a>.</p><h2 id="design-requirements" tabindex="-1">Design requirements <a class="header-anchor" href="#design-requirements" aria-label="Permalink to &quot;Design requirements&quot;">​</a></h2><ul><li>Reuse the HiveBoard mounting interface and specify the space required around the asset.</li><li>Define the grasping surfaces, moving parts, travel limits, and operating sequence.</li><li>State whether the task uses one hand or two. A two-handed task can also be discussed under the <a href="/hiveboard-docs/contribute/bimanual">bimanual call</a>.</li><li>Make the success state visible to an external camera.</li><li>Provide a reset procedure that another laboratory can follow without adjusting the task difficulty between trials.</li><li>Document wear, consumables, non-printed parts, and any precautions required during use.</li></ul><h2 id="propose-an-asset" tabindex="-1">Propose an asset <a class="header-anchor" href="#propose-an-asset" aria-label="Permalink to &quot;Propose an asset&quot;">​</a></h2><p>Email <a href="mailto:ricardo.godoy@usp.br?subject=HiveBoard%20ADL%20asset%20proposal" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a> with:</p><ol><li>Your name, affiliation if applicable, and proposed asset name.</li><li>The everyday task and the motions needed to complete it.</li><li>A sketch, reference image, or existing prototype.</li><li>The initial state, success condition, and reset procedure.</li><li>The files and physical or simulation testing you expect to provide.</li></ol><p><strong>Contact the authors before starting detailed design</strong> to check suitability and coordinate overlapping proposals. See <a href="/hiveboard-docs/contribute/requirements">requirements and credit</a> for the complete submission package and authorship eligibility.</p>',13)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
